// Attaches documented encounter details (data/unbound/encounters.data.js) to
// the Unbound routes served to the tracker. Pure module; relative imports
// only so it runs in both the server and Node (tests).
//
// routes.json already holds each route's species list (the picker's
// suggestions, generated by tools/build-unbound-encounters.mjs). This only
// adds `encounterDetails` to documented routes; keys, order, `encounters` and
// every other field are returned unchanged. Species in `encounters` without
// details are the older list's unverified fallback.
import DATA from '../data/unbound/encounters.data.js'
import { rowsBySpecies } from './encounter-groups.js'

export const pageUrl = (page) => `${DATA.source}/wiki/${encodeURIComponent(page.replace(/ /g, '_'))}`

export function encounterDetailsFor(route, data = DATA) {
  const loc = route.type === 'route' && data.locations[route.name]
  if (!loc) return null
  return {
    page: loc.page,
    url: pageUrl(loc.page),
    revid: loc.revid,
    license: data.license,
    species: rowsBySpecies(loc.rows)
  }
}

export function withEncounterDetails(routes, data = DATA) {
  return routes.map((route) => {
    const encounterDetails = encounterDetailsFor(route, data)
    return encounterDetails ? { ...route, encounterDetails } : route
  })
}
